<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><title>Veřejná mapa stromů a ploch</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="community.css?v=3">
<link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css">
<header><strong id="title">Veřejná mapa stromů a ploch</strong><label>Hledat <input id="search" type="search" placeholder="Číslo nebo veřejný údaj"></label><label><input type="checkbox" id="trees" checked> Stromy</label><label><input type="checkbox" id="areas" checked> Plochy</label><span id="status" role="status"></span><button id="deviceLocation" type="button" aria-pressed="false">Moje poloha</button><span id="locationStatus" role="status"></span><button id="toggleTable" type="button" aria-expanded="false">Tabulka</button></header>
<details id="controls"><summary>Zobrazení a filtrování</summary><div class="controls">
<label>Pozadí značky <select id="symbol"><option value="white">Bílé</option><option value="transparent">Průhledné</option></select></label>
<label>Velikost podle <select id="sizeMode"><option value="girth">Obvod kmene</option><option value="dbh">Průměr kmene</option><option value="spread">Šířka koruny</option><option value="height">Výška stromu</option><option value="none">Stejná velikost</option></select></label>
<label><input id="labels" type="checkbox"> Čísla v mapě</label>
<label>Barvení podle <select id="colorField"><option value="">Jednotné</option></select></label>
<label>Filtrovat údaj <select id="filterField"><option value="">Bez filtru</option></select></label>
<label>Podmínka <select id="filterOp"><option value="contains">Obsahuje</option><option value="eq">Je rovno</option><option value="ne">Není rovno</option><option value="gt">Větší než</option><option value="lt">Menší než</option><option value="empty">Nevyplněno</option><option value="filled">Vyplněno</option></select></label>
<label>Hodnota <input id="filterValue" type="text"></label><button id="resetFilter" type="button">Zrušit filtry</button>
</div><div id="legend" aria-label="Legenda barev"></div></details><main><div id="map" aria-label="Mapa"></div><aside id="detail" hidden><button id="close" type="button">Zavřít</button><div id="card"></div></aside></main><section id="tablePanel" hidden aria-label="Tabulka veřejných objektů"><div class="table-scroll"><table><thead id="tableHead"></thead><tbody id="tableBody"></tbody></table></div><div class="pager"><button id="prev" type="button">Předchozí</button><span id="page"></span><button id="next" type="button">Další</button></div></section>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script><script>window.TreeApp={};</script><script src="../js/markers.js?v=2.25-public"></script><script src="community.js?v=20261118-clusters"></script></html>

